B.bc3=s(["Anliy","En ligne","Online"],t.s)
B.aE3=s(["San ent\xe8n\xe8t","Hors ligne","Offline"],t.s)
B.aTy=s(["Senkronizasyon ap f\xe8t","Synchronisation en cours","Synchronizing"],t.s)
